{"cards": [{"node_code": "N_c0016245ca0c6cff", "definition": "研究中国境内铁路与其他运输方式（公路、水运、航空、管道）之间，以及铁路内部不同区段、局段之间的联合运输组织、经济核算、利益分配及政策协调的学科分支。", "boundary": "本节点聚焦于“联运”的经济与管理属性，而非纯技术衔接。边界在于区分“联运经济”与“单一方式经济”：仅涉及铁路内部调度归入铁路运输管理或成本节点；涉及跨方式衔接、多式联运规则、国际联运协定（侧重中国参与部分）及联运带来的经济效益分析归入本节点。若内容侧重物理设施衔接（如换装站设计），应归入相应工程节点。", "includes": ["中国铁路与公路、水运、航空等多式联运的组织模式与经济分析", "中国铁路内部跨局、跨段联运的清算规则、利益分配机制", "中国参与国际铁路联运的经济政策、协定执行及历史沿革"], "excludes": ["纯铁路内部单一区段的运输组织与调度技术", "非铁路主导的纯公路或水运联运经济分析"], "sibling_distinctions": [{"other_code": "N_787ee44c9bb618d6", "rule": "区分依据为“单一环节”与“联合环节”：侧重铁路自身成本构成、运价制定归入成本运价节点；侧重跨方式或跨区段联运中的费用分摊、联合运价及协调机制归入本节点。"}, {"other_code": "N_8224032a29170d9c", "rule": "区分依据为“企业主体”与“业务模式”：侧重铁路企业的组织架构、人力资源管理、内部治理归入企业管理节点；侧重联运业务的具体操作流程、外部协调及经济效果归入本节点。"}], "cross_boundary_rule": "若内容涉及“中欧班列”等具体联运项目，若侧重其运营组织、国际协调及经济影响，主挂载本节点；若侧重其具体的铁路车辆技术或线路工程，则归入相应工程节点。"}, {"node_code": "N_787ee44c9bb618d6", "definition": "研究中国铁路运输过程中成本构成、核算方法、运价体系、票价制定及其经济规律、政策调整与改革实践的学科分支。", "boundary": "本节点聚焦于中国铁路的“价格与成本”经济属性。边界在于区分“经济定价”与“技术运营”：涉及机车能耗、线路维护等纯技术参数归入工程节点；涉及基于这些参数的成本模型、运价公式、票价政策、补贴机制及市场化定价改革归入本节点。若涉及联运价格，侧重铁路内部成本归本节点，侧重跨方式分摊归联运节点。", "includes": ["中国铁路运输成本核算体系、成本构成分析及控制方法", "中国铁路货物运价、旅客票价制定原则、调整机制及历史演变", "中国铁路运价政策、补贴制度及市场化定价改革实践"], "excludes": ["铁路基础设施（线路、车辆）的纯工程技术参数", "非铁路领域的通用物流成本或供应链管理理论"], "sibling_distinctions": [{"other_code": "N_c0016245ca0c6cff", "rule": "区分依据为“单一方式定价”与“联合方式定价”：侧重铁路自身运价结构、成本归集归入本节点；侧重多式联运中的联合运价、费用清算及跨方式协调归入铁路联运节点。"}, {"other_code": "N_8224032a29170d9c", "rule": "区分依据为“价格机制”与“企业管理”：侧重运价、票价的经济规律、政策制定及成本效益分析归入本节点；侧重企业内部的财务管理制度、预算执行及绩效考核归入企业管理节点。"}], "cross_boundary_rule": "若内容涉及“铁路货运价格改革”，若侧重价格形成机制、成本补偿原则及政策背景，主挂载本节点；若侧重改革对企业组织结构或市场策略的影响，可关联企业管理，但主挂载仍为本节点。"}, {"node_code": "N_8224032a29170d9c", "definition": "研究中国铁路运输企业的组织形式、管理体制、内部运营、人力资源、财务制度及企业改革历程的学科分支。", "boundary": "本节点聚焦于中国铁路“企业主体”的管理与经济属性。边界在于区分“企业管理”与“宏观政策/具体业务”：侧重国家层面的铁路方针政策归入方针政策节点；侧重具体运输组织技术归入管理工程；侧重企业内部的组织架构、法人治理、劳动用工、财务核算、绩效考核及企业改制归入本节点。", "includes": ["中国铁路企业的组织体制、法人治理结构及内部管理制度", "中国铁路运输企业的财务管理、劳动人事、绩效考核及改革实践", "中国铁路企业的经营战略、市场开发及经济效益分析"], "excludes": ["国家层面的宏观铁路方针政策（归入方针政策节点）", "纯技术性的运输调度、信号控制等运营工程内容"], "sibling_distinctions": [{"other_code": "N_3082c503a0330193", "rule": "区分依据为“宏观体制”与“微观企业”：侧重国家计划管理体制、行业监管政策归入计划与管理体制节点；侧重具体铁路企业的内部组织、运营管理及企业行为归入本节点。"}, {"other_code": "N_787ee44c9bb618d6", "rule": "区分依据为“管理行为”与“价格机制”：侧重企业内部的成本控制流程、财务管理制度归入本节点；侧重运价、票价的经济规律、定价政策及成本理论归入成本运价节点。"}], "cross_boundary_rule": "若内容涉及“铁路局改制”，若侧重改制过程中的组织结构调整、人员安置及内部制度变革，主挂载本节点；若侧重改制对宏观铁路管理体制或国家政策的影响，可关联计划与管理体制，但主挂载仍为本节点。"}]}
